const d=[{id:"F01",title:"Sahîh-i Buhârî 1 · Ameller ve niyetler",url:"https://sunnah.com/bukhari:1",type:"religious",finding:"Hz. Ömer, Peygamber’in ameller ve niyetlerle ilgili öğretisini aktarır.",limitation:"Bu, dinî bir kaynak; deneysel çalışma değil. ODA’nın günlük iş alıştırması bir yorumdur; hadisin kendi sözü veya dinî hüküm değildir. Uygulama samimiyeti ya da sevabı yargılayamaz."},{id:"F02",title:"Sahîh-i Buhârî 6491 · Niyet edilen ve yapılan işler",url:"https://sunnah.com/bukhari:6491",type:"religious",finding:"İbn Abbas’ın aktardığı bölüm, niyet edilen ve yapılan iyi ve kötü işlerin kaydını anlatır.",limitation:"Bu kaynaktaki dinî ayrıntılar psikolojik bir yasa değildir. ODA’nın hazırlık ve davranış kayıtları yapılan işi anlatır; dinî ödülü belirleyemez."},{id:"F03",title:"Kur’an · Âl-i İmrân 3:159",url:"https://quran.com/3/159",type:"religious",finding:"Bu ayette istişare, karar ve tevekkül bir arada yer alır.",limitation:"ODA bu kaynaktan isteğe bağlı, günlük bir düşünme alıştırması çıkarır. Tevekkülün ancak hazırlıktan sonra başladığına dair genel bir kural koymaz. Ayetin bütün anlamını açıklamaz veya sonucu garanti etmez."},{id:"F07",title:"Sünen-i Ebû Dâvûd 4811 · İnsanlara teşekkür",url:"https://sunnah.com/abudawud:4811",type:"religious",finding:"Ebû Hüreyre’nin aktardığı öğreti, insanlara teşekkür etmeyi Allah’a şükretmekle bağlar. Kayıtta Elbânî’nin sahih değerlendirmesi gösterilir.",limitation:"Bu, dinî bir öğreti; psikolojik etki kanıtı değil. Somut teşekkür cümlesi ODA’nın uyarlamasıdır. Kaynak bilgilerini kontrol etmek, hadisin geçerliliği hakkında yeni bir hüküm vermek değildir. Güvenli olmayan biriyle iletişimi de zorunlu kılmaz."},{id:"F08",title:"Kur’an · İnşirâh 94:5–6",url:"https://quran.com/94/5-6",type:"religious",finding:"Zorlukla beraber kolaylık, dinî bir umut kaynağı sunar.",limitation:"Yaşadığın güçlüğün bugün veya seçtiğin tarihte biteceğini garanti etmez. ODA’nın destek adımı bir uyarlamadır. Klinik etki göstermez veya ayetlerin bütün anlamını açıklamaz."},{id:"F11",title:"Sahîh-i Buhârî 6464 · Küçük düzenli işler ve ölçülülük",url:"https://sunnah.com/bukhari:6464",type:"religious",finding:"Hz. Âişe, küçük düzenli işleri ve ölçülü olmayı vurgulayan öğretiyi aktarır.",limitation:"Bölümün bütünü ameller ve kurtuluşla da ilgilidir. Uygulamayı art arda yaptığın günlerin sayısı imanı veya kurtuluşu ölçmez. Sınırı belli iyilik planı ODA uyarlamasıdır."},{id:"F13",title:"Ano ve Vasconcelles · 2005 · Dinî başa çıkma ve uyum",url:"https://mhwbf.org/wp-content/uploads/2019/02/Ano-2005-Religious-coping-and-psychological-ad.pdf",type:"research",finding:"Çoğu gözlemsel 49 çalışmada dinî başa çıkma, uyumla ilişkiliydi. Tablo 5’te birleştirilmiş Fisher z değerleri, olumlu başa çıkma/olumlu uyum için 0,33 [0,30; 0,35], olumsuz başa çıkma/olumsuz uyum için 0,22 [0,19; 0,24] idi.",limitation:"Bu değerler ham korelasyonlar değil; neden ve sonuç ilişkisini de kanıtlamıyor. İnanç grubu bildirilen 8.115 katılımcının %57’si Protestan, %28’i Katolikti. Sonuçları başka etkenler de açıklayabilir. Veriler kişilerin kendi bildirimine dayanıyor; bulguların İslami uygulamaya aktarılması sınırlı. Araştırma kategorileri sana dair yargı değildir."},{id:"F14",title:"Kirca ve diğerleri · 2023 · İfade edilen şükran ve iyi oluş",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"23 çalışma ve 25 örneklemde ifade edilen şükran, nötr karşılaştırma koşullarına göre iyi oluşta küçük bir ortalama fayda gösterdi: g = 0,22, %95 güven aralığı [0,11; 0,33]. Başka iyi oluş etkinliklerine karşı g = 0,12 [−0,02; 0,26].",limitation:"Diğer iyi oluş etkinliklerinden daha etkili olduğu veya terapiyle aynı etkiyi verdiği gösterilmedi. Katılımcıların çoğu klinik gruplardan değildi. Makaledeki katılımcı toplamları tutarsız; ikisini de kullanmıyoruz. Dinî etkiyi kanıtlamaz, iletişimi zorunlu kılmaz veya kişisel fayda garanti etmez."},{id:"F15",title:"Choi ve diğerleri · 2025 · Kültürler arasında şükran",url:"https://www.pnas.org/doi/10.1073/pnas.2425193122",type:"research",finding:"28 ülkede 145 makale ve 163 örneklemde şükran müdahalelerinin iyi oluşta küçük ortalama etkisi vardı: g = 0,19, %95 güven aralığı [0,15; 0,22]. Gelecekteki çalışma için tahmin aralığı [−0,21; 0,59] idi.",limitation:"Katılımcıların çoğu klinik gruplardan değildi; yöntemler farklıydı. Etkiler değişiyor ve tahmin aralığı sıfırı içeriyor. Kendin için yazdığın tek bir cümlenin etkisini doğrulamaz. Bir kişide ne olacağını öngörmez veya İslami şükrün üstünlüğünü göstermez."},{id:"F16",title:"Curry ve diğerleri · 2018 · İyilik ve yapan kişinin iyi oluşu",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"27 çalışma ve 4.045 katılımcıda iyilik davranışları, yapan kişinin iyi oluşunda mütevazı ortalama fayda gösterdi: δ = 0,28, %95 güven aralığı [0,16; 0,41].",limitation:"Çalışmalar farklıydı; katılımcıların çoğu klinik gruplardan değildi. Yardımı yapan veya alan herkese fayda garanti etmez. Tedavi etkisi göstermez veya dinî ödülü ölçmez. Sınırsız fedakârlığı desteklemez. Yanlılık ya da etkiyi değiştiren bir etken bulunmaması, bunların olmadığını kanıtlamaz."},{id:"F18",title:"Nelson ve diğerleri · 2016 · Başkasına yararlı davranış deneyi",url:"https://sonjalyubomirsky.com/wp-content/uploads/2024/03/Nelson-Layous-Cole-Lyubomirsky-2016.pdf",type:"research",finding:"Başkalarına iyilik grubundan, dört hafta boyunca haftada bir günde üç iyilik yapması istendi. İki hafta sonra takip ölçümü yapıldı. Başkalarına yararlı davranış grupları birleştirilip kontrol grubuyla karşılaştırıldığında, iyi oluştaki gelişimin tahmini d = 0,31, p = 0,05 idi.",limitation:"Özette N = 473 yazıyor; rastgele atanan grupların toplamı 472. Gelişim analizlerine ise 464 kişi dahil edildi. Güven aralığı ve ön kayıt doğrulanmadı. ODA’nın tek davranış biçimi deneyden farklı; herkese fayda vaat etmez."},{id:"F19",title:"Wang ve diğerleri · 2021 · Engele bağlı planlar ve hedefe ilerleme",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"15.907 katılımcıyı kapsayan 21 makale ve 24 bağımsız etki incelendi. Zihinsel karşılaştırmayı “şu olursa bunu yaparım” planlarıyla birleştirmek hedefe ulaşmayı ortalama olarak destekledi: g = 0,336, %95 güven aralığı [0,229; 0,443].",limitation:"Hedefler ve uygulama biçimleri farklıydı. Yayın yanlılığı için yapılan düzeltme tahmini etkiyi azalttı. Samimi niyetin tek başına etkisini veya duanın başarıya neden olduğunu göstermez. İnanca özel kontrol listesini ya da on dakikanın en iyi hazırlık süresi olduğunu doğrulamaz."},{id:"F20",title:"NIMH · 2026 · Ruh sağlığına özen göstermek",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Uzun süren sıkıntı ve günlük işlerde zorlanma uzman desteğini gerektirir. Krizde hemen yardım gerekir.",limitation:"Bu, halka yönelik bir rehber. Tanı koymaz veya manevi bir nedeni kanıtlamaz. Yardım istemek için iki haftanın geçmesini ya da dersi bitirmeyi beklemen gerekmez. Dua ve manevi danışma sağlık hizmetinin yerini tutmaz."},{id:"faith-kindness",title:"Curry ve diğerleri · 2018 · İyilik ve yapan kişinin iyi oluşu",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"27 çalışma ve 4.045 katılımcıda iyilik davranışları, yapan kişinin iyi oluşunda mütevazı ortalama fayda gösterdi: δ = 0,28, %95 güven aralığı [0,16; 0,41].",limitation:"Çalışmalar farklıydı; katılımcıların çoğu klinik gruplardan değildi. Yardımı yapan veya alan herkese fayda garanti etmez. Tedavi etkisi göstermez veya dinî ödülü ölçmez. Sınırsız fedakârlığı desteklemez. Yanlılık ya da etkiyi değiştiren bir etken bulunmaması, bunların olmadığını kanıtlamaz."}],i=[{schemaVersion:2,revision:2,id:"faith-1",courseId:"faith",locale:"tr",title:"O iyi niyet hâlâ sırada bekliyor",goal:"Verdiğin sözün, seçtiğin değeri yansıtan ve işe yarayan küçük bir kısmını gerçekten yap.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Yardım etmeye niyet ettin. Bugün sözünün küçük, işe yarayan bir kısmını yap.",reason:{id:"faith-1-purpose-cost",label:"Kimse övmese de hangi kısmı yapmayı seçerdin?",kind:"text",maxLength:160,optional:!0,suggestions:["Verdiğim sözü tutmak","Sınırlarımı koruyarak yardım etmek","Önemsediğim değere göre davranmak"]},why:{id:"faith-1-why",label:"Kimse övmese de hangi kısmı yapmayı seçerdin?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Buhârî’nin ilk hadisi, ameller ve niyetlerle ilgilidir. Peygamber’in sözünü Hz. Ömer aktarır. Buradaki günlük iş alıştırması ise ODA’nın yorumudur. Verdiğin bir sözü seç. Uygulama niyetini yargılayamaz. Sen bu işi neden yapmak istediğini düşün ve o amaca uygun küçük bir iş seç. Kaynak ile bu alıştırma aynı şey değildir.","Yardım etmek isteyebilir, aynı zamanda takdir de bekleyebilirsin. Burada niyetinin kusursuz olduğunu kanıtlaman gerekmiyor. Neye hizmet etmek istediğini seç, sonra kararlaştırdığın bir parçayı yap. İşin kendisi mümkün değilse hazırlık, hazırlık olarak kalır. İstersen inancınla ilgili düşüncelerini ODA dışında tut. İsteğe bağlı yanıtlar derse veya plana kaydedilir. Koçla paylaşım için ayrı izinler vardır."],example:{title:"Yusuf küçük sözünü tutuyor",text:"Yusuf komşusuna telefon kullanımı için kısa bir rehber sözü verdi. Öğle molasında hem yardım etmek hem güvenilir görünmek istiyor. Yardım etmeyi seçip bir arama için kararlaştırdıkları adımları gönderiyor. Komşusu o öğleden sonra yanıt vermiyor. Yusuf mesajın gönderildiğini kaydediyor. Niyetlerini kendine saklıyor. Rehberin işe yarayıp yaramadığını, henüz bilmiyorken olmuş gibi yazmıyor."}},move:{invitation:"Verdiğin sözün işe yarayan bir kısmını yap. Örneği kendi anlaşmanıza göre düzenle.",instructions:["Söz verdiğin işi, güvenli kişiyi, iletişim yolunu ve başlama anını belirle. Planını özel tutabilirsin.","Ne yapacağınızı zaten kararlaştırdıysanız o anlaşmayı kullan. Göndermek asıl iştir. Yalnızca metni yazmak hazırlıktır."],prompts:[],suggestions:{action:["Örnek: Merve’ye telefon ayarı için kararlaştırdığımız bağlantıyı gönder","Yusuf’a söz verdiğim iki kupayı yıka","Serkan’a kararlaştırdığımız randevu yol tarifini gönder"],minimum:["Merve’ye telefon ayarı için anlaştığımız bağlantıyı gönder","Üzerime aldığım iki kupayı da yıka","Kararlaştırdığımız otobüs durağı tarifini gönder"],cue:["Öğle yemeğimi bitirdikten hemen sonra","Birlikte yediğimiz yemek bittikten hemen sonra","Serkan’ın randevu hatırlatıcısı geldiği anda"],place:["Mevcut mesajlaşmamızda","Kullanabildiğimiz mutfak lavabosunda","Randevu için kullandığımız mesajlaşmada"],minutes:[2,1],fallback:["Mesaj gitmezse kararlaştırdığımız e-posta yolunu kullan","Yapabildiğim başka bir yararlı temizlik işi için anlaş","Kararlaştırdığımız, kullanabildiğim iletişim yolunu kullan"],observation:["Bağlantı gönderildi; yararı ve yanıt henüz bilinmiyor","İş mi yapıldı, yalnızca hazırlık mı?","Tarif gönderildi; yine de yanıt gelmeyebilir"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: Merve’ye telefon ayarı için kararlaştırdığımız bağlantıyı gönder",minimum:"Merve’ye telefon ayarı için anlaştığımız bağlantıyı gönder",cue:"Öğle yemeğimi bitirdikten hemen sonra",place:"Mevcut mesajlaşmamızda",fallback:"Mesaj gitmezse kararlaştırdığımız e-posta yolunu kullan",observation:"Bağlantı gönderildi; yararı ve yanıt henüz bilinmiyor",minutes:2},{action:"Yusuf’a söz verdiğim iki kupayı yıka",minimum:"Üzerime aldığım iki kupayı da yıka",cue:"Birlikte yediğimiz yemek bittikten hemen sonra",place:"Kullanabildiğimiz mutfak lavabosunda",fallback:"Yapabildiğim başka bir yararlı temizlik işi için anlaş",observation:"İş mi yapıldı, yalnızca hazırlık mı?",minutes:1},{action:"Serkan’a kararlaştırdığımız randevu yol tarifini gönder",minimum:"Kararlaştırdığımız otobüs durağı tarifini gönder",cue:"Serkan’ın randevu hatırlatıcısı geldiği anda",place:"Randevu için kullandığımız mesajlaşmada",fallback:"Kararlaştırdığımız, kullanabildiğim iletişim yolunu kullan",observation:"Tarif gönderildi; yine de yanıt gelmeyebilir",minutes:2}]},suggested:{action:"Örnek: Merve’ye telefon ayarı için kararlaştırdığımız bağlantıyı gönder",minimum:"Merve’ye telefon ayarı için anlaştığımız bağlantıyı gönder",minutes:2,cueHint:"Öğle yemeğimi bitirdikten hemen sonra",placeHint:"Mevcut mesajlaşmamızda",obstacleHint:"Örnek: göndermek yerine niyetimi açıklamakla uğraşıyorum",fallbackHint:"Mesaj gitmezse kararlaştırdığımız e-posta yolunu kullan",observationHint:"Bağlantı gönderildi; yararı ve yanıt henüz bilinmiyor"},stopRule:"Yalnızca güvenli, gönüllü ve sınırlarına uygun davranışları seç.",accessibleAlternative:"Kendi iletişim yöntemini kullan. İstersen planın bütün ayrıntılarını ODA dışında tut."},result:{question:"Seçtiğin işe yarayan davranışı gerçekten yaptın mı?",observationPrompt:"Özel niyetlerini paylaşmadan, gerçekte ne yaptığını söyleyebilir misin?"},judgment:{primary:{id:"faith-1-decision",scenario:"Yusuf bir sınıf arkadaşına işe yarayan notlar sözü verdi. Notlar hazır. Hem yardım etmek hem takdir görmek istiyor. Göndermek güvenli; arkadaşı da notları bekliyor.",question:"Hangi seçim, kararlaştırılmış bu sözü yerine getirir?",options:[{id:"private-reflection",text:"Hazır notları gönderip göndermemeye karar vermeden önce, niyetini daha iyi anlamak için bir gün daha yalnız başına düşünsün.",feedback:"Kendi içinde düşünmek değerli olabilir. Burada güvenli, kararlaştırılmış malzeme hazır. Niyetin daha temiz olmasını beklemek yardımı erteliyor. Yusuf, kusursuzluğu ön şart yapmadan da kendi niyeti üzerine düşünebilir."},{id:"send-agreed-notes",text:"Yardım etmeyi seçsin, övgüyü şart koşmadan arkadaşının beklediği hazır notları doğrudan ona göndersin.",feedback:"Bu seçim, birden çok niyetin olmasına izin verirken verilen sözü yerine getiriyor. Kayda yalnızca notların gönderildiğini yazarsın; bu, samimiyetinin kanıtı değildir. Arkadaşının yanıt vermesi veya fayda görmesi ayrı bir gözlemdir."},{id:"explain-intention",text:"Önce arkadaşına niyetini anlatsın. Yanıt gelince hazır notları göndermeyi teklif etsin.",feedback:"Niyetini anlatmak sana dürüst bir seçim gibi gelebilir. Ama arkadaşından, beklediği yardımı almadan önce Yusuf’un niyetiyle ilgilenmesini istiyor. Yusuf düşüncesini kendine saklayabilir; hazır ve işe yarayan notları ayrıca onay beklemeden doğrudan gönderebilir."}],bestOptionId:"send-agreed-notes"}},carry:{takeaway:"Amacına uygun, işe yarayan küçük bir iş yap. Özel niyetlerin sana kalsın.",followUp:{questionId:"faith-1-return",question:"Yaptığın iş seçtiğin amaca hizmet etti mi, yoksa henüz yalnızca hazırlık mıydı?",observationPrompt:"Özel niyetlerini paylaşmadan, gerçekte ne yaptığını söyleyebilir misin?",adjustmentPrompt:"Bir sonraki denemenin sana uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Dinî anlam ile davranış kaydı ayrı kalır",paragraphs:["Sahîh-i Buhârî 1’de Hz. Ömer, Peygamber’in ameller ve niyetlerle ilgili sözünü aktarır. ODA’nın alıştırması, seçtiğin amacın günlük bir sözüne nasıl yön verebileceğini sorar. Bu, güncel bir eğitim yorumudur. Hadisin kendi sözü, bütün anlamını açıklayan bir yorum veya dinî hüküm değildir. [F01] Niyetini uygulamaya yazmadan da kendi içinde düşünebilirsin.","Buhârî 6491, niyet edilen ve yapılan işleri bunların kaydıyla ilgili dinî bir anlatım içinde ele alır. Davranış günlüğü bu anlatımı tamamlanma puanına indirgeyemez; sevabı belirleyemez. [F02] “Tarifi hazırladım” ve “kararlaştırdığımız tarifi gönderdim” farklı davranış kayıtlarıdır. İkisi de ODA’ya ne kadar samimi olduğunu söylemez. Plan, sınav yanıtı, uygulama serisi veya ara verme, imanını yargılamak için dayanak değildir. İş mümkün değilse hazırlığı dürüstçe seçebilirsin. Yararlı olacaksa hazırladığını ne zaman kullanabileceğini ayrıca belirle."]},{heading:"Amacını hayata geçirmek için plan yap",paragraphs:["Bir hedef planlama derlemesi, 21 makaledeki 24 bağımsız etkiyi birleştirdi. İstenen hedefi gerçek engelle karşılaştırıp engele bağlı plan yapmak, hedefe ulaşmayı ortalama olarak destekledi. Yayın yanlılığına göre düzeltme, tahmini faydayı azalttı; uygulama biçimleri ve hedefler farklıydı. Bu, birden çok adımı birleştiren planlamaya dair psikolojik kanıttır. Sevabın, duanın etkisinin veya bu dersin özel kontrol listesinin kanıtı değildir. [F19]","ODA bu fikri işe yarayan bir davranış, tanıyabileceğin başlama anı, uygun yer ve olası engele bir yanıt seçerek uyarlıyor. Haftanda önemli olan günlük bir söz seç ve ders boyunca onunla çalış. Sonraki dersler ancak ihtiyaç çıktığında hazırlığı düzenlemene, gerçek yardımı fark etmene veya destek eklemene yardımcı olur. Birden çok niyetin olması, onları açıklamak zorunda olduğun anlamına gelmez. İstersen planı tamamen kendine sakla. O zaman ODA yalnızca dönüş seçimini hatırlayabilir. Hiç almadığı davranış ayrıntılarını sonradan sana getiremez."]}],sourceIds:["F01","F02","F19"]}},{schemaVersion:2,revision:2,id:"faith-2",courseId:"faith",locale:"tr",title:"Yine mi kontrol? Sözünün sana düşen kısmını yap.",goal:"Gerekenler hazırsa sözünü yerine getir. Gerçek hazırlık eksiği varsa tek açığı, duracağın sınırı belirleyerek gider.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Hazır ama hâlâ kontrol mü ediyorsun? Bir kontrol daha yapacaksan gerçek bir eksik olsun.",reason:{id:"faith-2-actual-gap-cost",label:"Hangi eksik kaldı? Bir kontrol daha neyi erteleyecek?",kind:"text",maxLength:160,optional:!0,suggestions:["Hazırsa kaydettiğim sözümü yerine getirmek","Bilgi eksikse yalnızca o açığı kontrol etmek","Saat belirsizse karşılıklı anlaşmak"]},why:{id:"faith-2-why",label:"Sıradaki gerçek adımın için ne kadar hazırlık yeterli?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Âl-i İmrân 3:159’da istişare, karar ve tevekkül bir arada yer alır. ODA bunu emek ve güven üzerine günlük bir düşünme fırsatı olarak kullanır. Tevekkül ancak hazırlık bitince başlar diye kural koymaz. Kendi payına düşeni ciddiye aldığında da sonucun belirsizliği sürebilir. Bunlar birbirini geçersiz kılmaz.","Seçtiğin sözüne dön. Gerçek bir eksik çıktıysa tek yararlı hazırlık seç ve nerede duracağını belirle. Gerekenler zaten hazırsa bir kontrol daha yerine işi yapmayı seç. Hazırlığın bittiğine, içinin rahatlamasına göre karar verme. Neyi tamamladığına bak. İstersen bu seçim sırasında kendi içinde dua edebilirsin. Zorunlu bir teknik değildir; istediğin sonucu da vaat etmez."],example:{title:"Yusuf bir kez kontrol ediyor",text:"Yusuf’un komşusu rehberdeki adımların kendi telefon modelinde çalışıp çalışmadığını soruyor. Yusuf mutfak masasında gereken bir adımı kontrol edip düzeltiyor. Planladığı kontrol bitince duruyor ve yarın için güvenli bir görüşme öneriyor. Komşusu henüz saati onaylamıyor. Yusuf hazırlığı tamamladığını kaydediyor, duasını özel tutuyor. Yarınki görüşmeyi bugünden yapılmış saymıyor. Hazırlık ile görüşme kaydı ayrı kalıyor."}},move:{invitation:"Hazırsa sözünü yerine getir. Gerçek eksik varsa tek bir hazırlık seç ve sınırını belirle.",instructions:["Verdiğin sözü koru. Belirli bir hazırlık eksiğin varsa “Bunu uyarla”, ardından “Hazırlık” seçeneğini kullan.","Ne zaman duracağını ve hazırladığını ne zaman kullanacağını yaz. Kullanacağın zaman belirsizse belirt.","Hazırlığı kaydedince yalnızca hazırlık planlanır. Asıl işi ne zaman, neyin ardından yapacağını takviminde ayrıca belirle."],prompts:[{id:"faith-2-gap-next-use",label:"Hangi eksiği gidereceksin? Nerede duracaksın? Hazırladığını ne zaman kullanacağın kesinleşti mi?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Örnek: Merve’nin telefon rehberi ayarını bir kez dene. Görüşme belirsiz. Tarihi ve başlama anını ODA dışında tutabilir, “Eylem” alanına yazabilirsin."}],suggestions:{action:["Örnek: Merve’ye telefon ayarı için hazır bağlantıyı gönder","Merve ile kararlaştırdığımız telefon yardımı görüşmesini yap"],minimum:["Merve’ye kararlaştırdığımız hazır bağlantıyı gönder","Kararlaştırdığımız ilk kişiyi telefondan nasıl arayacağını anlat"],cue:["Öğle yemeğimi bitirdikten hemen sonra","Kesinleştirdiğimiz saat 18.00 görüşmesi başlayınca"],place:["Mevcut mesajlaşmamızda","Kullanabildiğimiz mevcut telefon görüşmesinde"],minutes:[2,5],fallback:["Mesaj gitmezse kararlaştırdığımız e-posta yolunu kullan","Merve uygun değilse başka bir tarih sor"],observation:["Bağlantı gönderildi; tekrar kontrol mü, yeni bilgi mi","Görüşme denendi; başka tarih hâlâ kesinleşmemiş olabilir"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: Merve’ye telefon ayarı için hazır bağlantıyı gönder",minimum:"Merve’ye kararlaştırdığımız hazır bağlantıyı gönder",cue:"Öğle yemeğimi bitirdikten hemen sonra",place:"Mevcut mesajlaşmamızda",fallback:"Mesaj gitmezse kararlaştırdığımız e-posta yolunu kullan",observation:"Bağlantı gönderildi; tekrar kontrol mü, yeni bilgi mi",minutes:2},{action:"Merve ile kararlaştırdığımız telefon yardımı görüşmesini yap",minimum:"Kararlaştırdığımız ilk kişiyi telefondan nasıl arayacağını anlat",cue:"Kesinleştirdiğimiz saat 18.00 görüşmesi başlayınca",place:"Kullanabildiğimiz mevcut telefon görüşmesinde",fallback:"Merve uygun değilse başka bir tarih sor",observation:"Görüşme denendi; başka tarih hâlâ kesinleşmemiş olabilir",minutes:5}]},suggested:{action:"Örnek: Merve’ye telefon ayarı için hazır bağlantıyı gönder",minimum:"Merve’ye kararlaştırdığımız hazır bağlantıyı gönder",minutes:2,cueHint:"Öğle yemeğimi bitirdikten hemen sonra",placeHint:"Mevcut mesajlaşmamızda",obstacleHint:"Örnek: eksik bilgi kalmadı, yine de kesinlik istiyorum",fallbackHint:"Mesaj gitmezse kararlaştırdığımız e-posta yolunu kullan",observationHint:"Bağlantı gönderildi; tekrar kontrol mü, yeni bilgi mi"},stopRule:"Seçtiğin sınırda dur. Sıkıntı günlük hayatını aksatıyorsa şimdi yardım iste.",accessibleAlternative:"Kullanabildiğin prova veya danışma yolunu seç. Dua etmek ve yazmak isteğe bağlı kalır."},result:{question:"Kaydettiğin işi, seçtiğin biçimiyle yaptın mı?",observationPrompt:"Asıl işin hangi kısmı yapıldı? Hangisi hazırlıktı? Sıradaki görüşme ya da kullanım zamanı hâlâ belirsiz mi?"},judgment:{primary:{id:"faith-2-decision",scenario:"Yusuf adımları denedi ve görüşme saatini kesinleştirdi. Yine de görüşmenin kötü geçmesinden endişe ettiği için aynı adımları tekrar tekrar kontrol ediyor.",question:"Kalan ihtiyaca hangi seçim daha uygun?",options:[{id:"longer-test",text:"Planladığı görüşmeden önce daha emin hissetmek için aynı adımları baştan sona bir kez daha denesin.",feedback:"Belirli bir eksik varsa yeni bir kontrol yardımcı olabilir. Burada adımlar kontrol edildi, saat kesinleşti. Tekrar etmek görüşmenin sonucunu garanti etmez. Asıl işi kararlaştırdığın zamanda yap."},{id:"cancel-call",text:"Yarınki görüşme yerine başka bir yazılı rehber hazırlasın, böylece canlı konuşma gerektirmeyen bir yolla hazırlanabilsin.",feedback:"Gerekiyorsa yazılı rehber erişilebilir bir seçenek olabilir. Burada kararlaştırılan görüşme hazır ve uygun. Yalnızca kesinlik aramak için biçimi değiştirmek, zaten yapılabilir olan sonraki adımdan uzaklaştırır."},{id:"keep-opportunity",text:"Bu hazırlık süresini bitirsin, yarınki kararlaştırılmış görüşmeyi korusun ve sonucun yine de belirsiz kalmasına izin versin.",feedback:"Bu seçim, kesinlik varmış gibi davranmadan yararlı hazırlığı ve seçtiğin sınırı koruyor. Yusuf neyin hazır olduğunu kaydeder, görüşmeyi kararlaştırılan anda dener. Kaygının azalması, işi tamamlamanın şartı değildir."}],bestOptionId:"keep-opportunity"}},carry:{takeaway:"Bugün yapabildiğin kısmı tamamla. Sonuç belirsiz kalabilir; sıradaki uygun an açıkça belli olsun.",followUp:{questionId:"faith-2-gap-execution-return",question:"Kayıtlı iş yapıldı mı? Varsa hazırlık gerçekten kalan bir eksikle bağlantılı mıydı?",observationPrompt:"Asıl işin hangi kısmı yapıldı? Hangisi hazırlıktı? Sıradaki görüşme ya da kullanım zamanı hâlâ belirsiz mi?",adjustmentPrompt:"Bir sonraki denemenin sana uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Emek ve tevekkül için katı bir sıra koymadan",paragraphs:["Âl-i İmrân 3:159 istişareyi, kararı ve tevekkülü bir araya getirir. ODA bu ayetten gönüllü bir günlük uygulama çıkarır: gerçek eksik hakkında sor, düşünerek bir seçim yap ve sana düşen, yapabildiğin kısmı yerine getir. Bu, günlük hayata yönelik bir yorumdur. Hazırlık listesi tamamlanana kadar tevekkül yoktur demez. İstediğin sonucun mutlaka gelmesini de vaat etmez. [F03]","Bu alıştırma nasıl tevekkül edeceğini belirlemez. Ne zaman duracağına dair sınır, günlük hazırlık işinle ilgilidir. İnancın üzerine düşünmenin bu seçimde yardımcı olup olmadığına sen karar verirsin. Yararlı hazırlığın bir soru, kontrol edilen bir adım veya tek prova olabilir. Seçtiğin sınırda bitir. Sonra asıl işi hangi tarihte ve neyin ardından yapacağını kendi takviminde ayrıca belirle. Henüz kesinleşmediyse bunu belirt. Hazırlığı kaydetmek o işi ve ertesi gün değerlendirmesini planlar. Sonraki görüşmeyi planlamaz. Planlı görüşme, yapılmış görüşme değildir. İstersen her iki aşamada da dua edebilirsin; duan sana özel kalır. İbadet miktarı veya iman puanı belirlenmez."]},{heading:"Yeterli hazırlık, pratik bir seçimdir",paragraphs:["Engele bağlı planlama araştırması, farklı ortamlarda somut hedef planlarının ortalama yararını destekler. Bu dinî çerçeveyi sınamaz; iki dakikanın en iyi süre olduğunu veya tekrar tekrar güvence aramanın sonucu iyileştirdiğini göstermez. [F19] ODA’nın ne zaman duracağını belirleme adımı, hazırlığın belirli bir ihtiyaca karşılık gelmesi için bir uyarlamadır. Bilgi eksikse o bilgiyi edin. Sonraki adım güvenli değilse veya kullanamıyorsan başka yol ya da uygun destek seç.","Sıkıntı, bozulan uyku veya günlük işlerde zorlanma sürüyorsa dinî düşünmenin yanında uzman desteği de alabilirsin. NIMH rehberi bunun manevi bir nedeni olduğunu söylemez; yardım istemeden önce iki hafta bekleme şartı koymaz. Krizde başka bir hazırlık alıştırması yerine hemen destek gerekir. [F20] Bilgili bir din danışmanı manevi konularda isteğe bağlı destek olabilir. Ama sağlık hizmetinin yerini tutmaz. Gerçekten yaptığın hazırlığı kaydet. Duygusal kesinliği ve dışarıdaki başarıyı, o hazırlığı tamamlamanın şartı haline getirme."]}],sourceIds:["F03","F19","F20"]}},{schemaVersion:2,revision:2,id:"faith-3",courseId:"faith",locale:"tr",title:"Yardım etti. Tam olarak ne yaptığını söyle.",goal:"Verdiğin sözü tutmana yardım eden birine dürüst bir teşekkür yaz. Paylaşmak sana kalır.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Aranızda anlaşmazlık varken yardım mı etti? Her şey yolundaymış gibi yapmadan teşekkür edebilirsin.",reason:{id:"faith-3-acknowledgment-tradeoff",label:"Teşekkürü zorlaştıran ne? Yaptığı hangi yardımı dürüstçe anlatabilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Yardımı kabul edip anlaşmazlığı ayrı tutmak","İletişimi güvenli ve isteğe bağlı tutmak","Yardım olmadıysa kendi sözümü sürdürmek"]},why:{id:"faith-3-why",label:"Bu sözünü tutarken sana kim yardım etti? İletişiminiz güvenli miydi?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Ebû Dâvûd 4811’de aktarılan öğretide insanlara teşekkür etmek, Allah’a şükretmekle bağlantılıdır. Buradaki kısa not, ODA’nın uyarlamasıdır. Seçtiğin söze yardımcı olan gerçek bir katkıyı adlandır. İlişkinin bütünü iyiymiş gibi anlatman gerekmiyor. O kişinin yaptığı yardım ile aranızda süren sorun ayrı ayrı gerçek olabilir.","Araştırmalar, ifade edilen şükranın iyi oluşta küçük bir ortalama faydasını buluyor. Sonuçlar değişken. Terapiyle eşit etkiyi kanıtlamıyor, daha iyi hissetmeni de şart koşmuyor. Bu yardımı anlatan bir not yaz. Bu not asıl sözünü yerine getirmiş sayılmaz. Kişinin ne yaptığını ve bunun sana nasıl yardım ettiğini kendin için yaz. Yazmak ile isteyerek göndermek ayrı işler. Yardım olmadıysa kendi sözünü sürdür."],example:{title:"Yusuf’un dürüst notu",text:"Yusuf’un kız kardeşi ona telefon kullanımı için anlaşılır bir rehber verdi. Başka bir aile konusunda hâlâ anlaşamıyorlar. Yusuf kendine yazıyor: “Rehberin, komşumuza ilk aramayı anlatmamı kolaylaştırdı.” İletişimden emin olmadığı için o akşam notu kendinde tutuyor. Anlaşmazlık sürüyor. ODA’ya içeriğini yazmadan yalnızca bir not yazdığını kaydediyor. Teşekkürün her şeyi çözdüğünü veya notun gönderildiğini söylemiyor."}},move:{invitation:"Gerçek yardımı adlandır. Bu teşekkür notu, verdiğin sözden ayrı bir iş olsun.",instructions:["“Bağlantılı ayrı bir eylem planla” seçeneğini kullan. Bu not asıl sözünü yerine getirmiş sayılmaz.","Gördüğün davranışı ve faydasını adlandır. Yalnızca güvenli, istenen iletişimle paylaş.","Yardım olmadıysa sözünü sürdür. Baskı varsa yalnızca o yardımı an veya ara ver."],prompts:[],suggestions:{action:["Örnek: Merve’nin rehberi için teşekkürümü kendime yaz","Serkan’ın salı vardiyasındaki yardımı için teşekkürümü kendime yaz"],minimum:["Yaz: Merve’nin rehberi telefonla aramayı anlatmamı kolaylaştırdı","Yaz: Serkan’ın yardımıyla kararlaştırdığım randevuya gidebildim"],cue:["Öğle yemeğimi bitirdikten hemen sonra","Kararlaştırdığımız vardiya bittikten hemen sonra"],place:["Yalnızca kendim için tuttuğum özel notlarda","Kullanabildiğim sessiz ve bana özel bir yerde"],minutes:[2,1],fallback:["Yalnızken sadece yapılanı ve faydasını söyle","Yalnızca vardiya yardımını anlat; anlaşmazlık sürüyor"],observation:["Not yazıldı veya söylendi mi? Asıl söz bekliyor.","Teşekkür ettim mi? Asıl sözün kaydı ayrı."],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: Merve’nin rehberi için teşekkürümü kendime yaz",minimum:"Yaz: Merve’nin rehberi telefonla aramayı anlatmamı kolaylaştırdı",cue:"Öğle yemeğimi bitirdikten hemen sonra",place:"Yalnızca kendim için tuttuğum özel notlarda",fallback:"Yalnızken sadece yapılanı ve faydasını söyle",observation:"Not yazıldı veya söylendi mi? Asıl söz bekliyor.",minutes:2},{action:"Serkan’ın salı vardiyasındaki yardımı için teşekkürümü kendime yaz",minimum:"Yaz: Serkan’ın yardımıyla kararlaştırdığım randevuya gidebildim",cue:"Kararlaştırdığımız vardiya bittikten hemen sonra",place:"Kullanabildiğim sessiz ve bana özel bir yerde",fallback:"Yalnızca vardiya yardımını anlat; anlaşmazlık sürüyor",observation:"Teşekkür ettim mi? Asıl sözün kaydı ayrı.",minutes:1}]},suggested:{action:"Örnek: Merve’nin rehberi için teşekkürümü kendime yaz",minimum:"Yaz: Merve’nin rehberi telefonla aramayı anlatmamı kolaylaştırdı",minutes:2,cueHint:"Öğle yemeğimi bitirdikten hemen sonra",placeHint:"Yalnızca kendim için tuttuğum özel notlarda",obstacleHint:"Örnek: anlaşmazlığımızı çözmek zorundaymışım gibi hissediyorum",fallbackHint:"Yalnızken sadece yapılanı ve faydasını söyle",observationHint:"Not yazıldı veya söylendi mi? Asıl söz bekliyor."},stopRule:"Teşekkür etmek için güvenli olmayan biriyle iletişim kurma veya yaşanan zararı yok sayma.",accessibleAlternative:"Yalnızken söyle veya kendin için yaz. Kime ve ne söylediğini paylaşmak sana kalır."},result:{question:"Seçtiğin teşekkürü gerçekten ifade ettin mi?",observationPrompt:"Yazdın mı, yalnızken söyledin mi, kendi seçiminle paylaştın mı?"},judgment:{primary:{id:"faith-3-honest-acknowledgment-decision",scenario:"Serkan, Yusuf’un salı vardiyasını üstlendi; Yusuf sağlık randevusuna gidebildi. Ayrı anlaşmazlıkları sürüyor. İletişim güvenli. Serkan gelecek hafta yardım edemeyeceğini ve şimdi yeni istek duymak istemediğini söyledi. Yusuf salı günkü yardıma teşekkür etmek istiyor.",question:"Hangi teşekkür, gerçeğe ve Serkan’ın belirttiği sınıra uyuyor?",options:[{id:"faith-3-misstated-help",text:"Serkan’a hem sağlık randevusunu ayarladığı hem de salı vardiyasını üstlenip Yusuf’un gitmesini sağladığı için teşekkür etsin.",feedback:"Serkan vardiyayı üstlendi. Örnekte randevuyu onun ayarladığı söylenmiyor. Teşekkürü gördüğün davranış ve faydayla sınırlı tut. Gerçeğe uygun teşekkür, çözülmemiş bir anlaşmazlıkla aynı anda var olabilir."},{id:"faith-3-specific-thanks",text:"Serkan’a salı vardiyası için teşekkür etsin; bu sayede sağlık randevusuna gidebildiğini söylesin, anlaşmazlık ayrı kalsın.",feedback:"Bu seçim gördüğün davranışı ve faydayı söylüyor, mevcut sınıra da uyuyor. Karışık duygular sürebilir. Yusuf notu kendine tutabilir veya gönüllü paylaşabilir. Ne asıl sözü ne de anlaşmazlığı bu teşekkürle kapanır."},{id:"faith-3-new-request",text:"Serkan’a salı vardiyası için teşekkür etsin ve gelecek hafta başka bir vardiyayı üstlenmesinin de neden yardımcı olacağını anlatsın.",feedback:"Teşekkürle açık bir istek yan yana gelebilir. Ama burada Serkan şimdi yeni istek istemediğini açıkça söyledi. Yenisi o sınırı göz ardı eder. Salı yardımını an; gelecekteki desteği başka yerde ara."}],bestOptionId:"faith-3-specific-thanks"}},carry:{takeaway:"Gerçek yardımı an. Bir not tek başına asıl sözünü yerine getirmez veya bütün kırgınlıkları çözmez.",followUp:{questionId:"faith-3-related-note-return",question:"Teşekkürün dürüst ve güvenli miydi? Asıl sözünün kaydı ondan ayrı kaldı mı?",observationPrompt:"Not yazıldı mı, söylendi mi, paylaşıldı mı? Asıl sözündeki hangi iş hâlâ bekliyor?",adjustmentPrompt:"Bir sonraki denemenin sana uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Somut teşekkür notu bir uyarlamadır",paragraphs:["Ebû Dâvûd 4811 insanlara teşekkür etmeyi Allah’a şükretmekle bağlar. Kaynak kaydı rivayeti Ebû Hüreyre’ye atfeder ve Elbânî’nin sahih değerlendirmesini gösterir. ODA’nın pratik notu güncel bir uyarlamadır. Kaynağın kendi sözü değildir; yeni bir hadis doğrulaması da değildir. [F07] Özel dinî düşüncelerini paylaşmadan, uygulamayı şükrünü yargılayan bir yere çevirmeden tek bir katkıyı anabilirsin.","Bu örnek cümle, birinin ne yaptığını ve senin gördüğün faydayı adlandırır. Yazma yardımıdır. Somut teşekkürün genel teşekkürden bilimsel olarak üstün olduğu doğrulanmış iddiası değildir. Güvenli bir kişinin yardımı gerçek olabilir; anlaşmazlık veya kırgınlık da gerçek kalabilir. Bunları ayrı tut. Kendin için yazmakla mesaj göndermek farklı davranışlardır. Hangisini gerçekten seçtiysen onu kaydet. Özel not, karşı tarafa ulaştırılmış bir şükran uygulaması diye anlatılamaz. Gönderdiğin mesaja yanıt gelmemesi de yapmış olduğun davranışı ortadan kaldırmaz."]},{heading:"Ortalama etki küçük; terapiye eşit denemez",paragraphs:["2023 tarihli ifade edilen şükran derlemesi 23 çalışma ve 25 örneklem içeriyordu. Nötr koşullarla karşılaştırıldığında iyi oluştaki ortalama etki küçüktü: g = 0,22, yüzde 95 güven aralığı 0,11 ile 0,33. Başka iyi oluş etkinliklerine karşı farkın aralığı sıfırı içeriyordu. Bu etkinlikler mutlaka yerleşmiş klinik tedaviler değildi. Üstünlük sınamasının anlamlı çıkmaması, terapiye eşitliği göstermez. Makaledeki tutarsız katılımcı toplamlarını burada kullanmıyoruz. [F14]","Daha büyük 2025 şükran derlemesi de küçük bir ortalama fayda buldu. Ama gelecekteki bir çalışma için tahmin aralığı sıfırı içeriyordu. Sonuçlar yönteme ve ortama göre değişti. [F15] İki derleme de dinî öğretiyi kanıtlamaz, kişisel fayda garanti etmez veya bu özel tek cümle biçimini doğrulamaz. Davranışı olumlu hissetmeden de tamamlayabilirsin. Notu, seçtiğin ilişkiye veya hayat yönüne hizmet ediyorsa kullan. Yararsız geliyorsa veya baskıya dönüşüyorsa uygulamayı değiştirebilir ya da bırakabilirsin."]}],sourceIds:["F07","F14","F15"]}},{schemaVersion:2,revision:2,id:"faith-4",courseId:"faith",locale:"tr",title:"Yükü yalnız mı taşıyorsun? Açıkça yardım iste.",goal:"Güvenli bir kişiden somut bakım desteği iste. Yardım yoksa kullanabileceğin başka bir yol seç.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Yükü yalnız mı taşıyorsun? Tek bir bakım veya sağlık ihtiyacın için yardım iste. İmanını bununla yargılama.",reason:{id:"faith-4-request-boundary-cost",label:"Güvenli bir yardım isteğini zorlaştıran ne? Hangi sınır bunu mümkün kılar?",kind:"text",maxLength:160,optional:!0,suggestions:["Tek, sınırları belli bir iş istemek","Paylaşacağım özel ayrıntıları sınırlamak","Bakımı üretken olma şartına bağlamamak"]},why:{id:"faith-4-why",label:"Hangi bakım, sürdürdüğün sözü daha güvenli hale getirir?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["İnşirâh’ta zorlukla beraber kolaylığı anlatan ayetler dinî umut sunar. Bu ayetler ne zaman rahatlayacağını söylemez. Gücünün yettiği bir sonraki fırsata bak. Bugün seçtiğin değerli adımın tamamı, bakım vermek veya almak olabilir. Yardım istemeyi ayrı bir iş olarak planla. Asıl sözün hâlâ yerine getirilmeyi bekler. İkisini ayrı kaydet.","Dinî başa çıkma araştırmaları ilişkiler gösterir. Manevi uygulamanın rahatlamaya neden olduğunu veya zorlanmanın zayıf iman demek olduğunu kanıtlamaz. Güvenli bir kişiye ya da uzmana tek, belirli bir istek ilet. Yardım edemezlerse uygun başka yolu kullan. İsteği yapmak senin davranışın; onların uygun olması sonuçtur. Özel şüphelerin ve ibadet ayrıntıların puana dönüştürülemez."],example:{title:"Yusuf başka yerden yardım istiyor",text:"Yusuf bakım verdikten sonra çok yorgun; komşuyla kararlaştırdığı görüşmeyi bu akşam yapamıyor. Erkek kardeşinden bir ev işini üstlenmesini istiyor ama kardeşi yapamıyor. Yusuf başka bir güvendiği akrabaya ulaşıyor ve komşusuna daha sonraki bir görüşmeyi öneriyor. Yardım hâlâ kesinleşmedi. Yusuf isteği yaptığını kaydediyor, mümkün olan dinlenmeyi kullanıyor. İnancını bunun üzerinden yargılamıyor."}},move:{invitation:"Günlük destek için güvenli bir kişiden tek, belirli bir iş için yardım iste.",instructions:["Acil ihtiyaçta günlük bir deneme planlamadan önce hemen kriz veya acil yardım al.","“Bağlantılı ayrı bir eylem planla” seçeneğini kullan. Yardımı, kişiyi, iletişim yolunu ve zamanı belirle.","Kabul edilmezse ulaşabildiğin başka hizmet veya güvenli bakım seç. Asıl sözün bu istekle tamamlanmaz."],prompts:[],suggestions:{action:["Örnek: Merve’den akşam bulaşık için mesajla yardım iste","Sağlık merkezimi arayıp uygun randevu saatlerini sor"],minimum:["Merve’den saat 19.00’da bulaşıkları yıkamasını iste","Sağlık merkezinden uygun bir randevu iste"],cue:["Kararlaştırdığımız gibi, 18.00’de bakımı devrettikten sonra","Sağlık merkezinin telefon hattı açıldığında"],place:["Mevcut mesajlaşmamızda","Rahatça telefon edebildiğim bana özel bir yerde"],minutes:[2,5],fallback:["Kabul edilmezse acil olmayan bulaşıkları bırak, dinlen","Sağlık merkezinin kullanabildiğim randevu yolunu kullan"],observation:["İstek gönderildi; yardımın gelmesi ayrı bir bilgi","İletişim kuruldu; randevu henüz kesinleşmemiş olabilir"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: Merve’den akşam bulaşık için mesajla yardım iste",minimum:"Merve’den saat 19.00’da bulaşıkları yıkamasını iste",cue:"Kararlaştırdığımız gibi, 18.00’de bakımı devrettikten sonra",place:"Mevcut mesajlaşmamızda",fallback:"Kabul edilmezse acil olmayan bulaşıkları bırak, dinlen",observation:"İstek gönderildi; yardımın gelmesi ayrı bir bilgi",minutes:2,kind:"support"},{action:"Sağlık merkezimi arayıp uygun randevu saatlerini sor",minimum:"Sağlık merkezinden uygun bir randevu iste",cue:"Sağlık merkezinin telefon hattı açıldığında",place:"Rahatça telefon edebildiğim bana özel bir yerde",fallback:"Sağlık merkezinin kullanabildiğim randevu yolunu kullan",observation:"İletişim kuruldu; randevu henüz kesinleşmemiş olabilir",minutes:5,kind:"support"}]},suggested:{kind:"support",action:"Örnek: Merve’den akşam bulaşık için mesajla yardım iste",minimum:"Merve’den saat 19.00’da bulaşıkları yıkamasını iste",minutes:2,cueHint:"Kararlaştırdığımız gibi, 18.00’de bakımı devrettikten sonra",placeHint:"Mevcut mesajlaşmamızda",obstacleHint:"Örnek: ilk sorduğum kişi bu akşam yardım edemiyor",fallbackHint:"Kabul edilmezse acil olmayan bulaşıkları bırak, dinlen",observationHint:"İstek gönderildi; yardımın gelmesi ayrı bir bilgi"},stopRule:"Krizde veya kendine zarar verme düşüncelerinde hemen yerel kriz desteğine ulaş. Acil tehlikede acil hizmetleri ara. Plan yapmadan önce yardım al.",accessibleAlternative:"Kullanabildiğin iletişim yolunu seç. Dua, ihtiyaç duyduğun bakımın yerini hiçbir zaman tutmaz."},result:{question:"Yardım isteğini ilettin mi veya bakım adımını attın mı?",observationPrompt:"Hangi bakım sağlandı, hangi ihtiyaç hâlâ karşılanmadı?"},judgment:{primary:{id:"faith-4-available-care-decision",scenario:"Leyla’nın bakım verdiği kişiyi bu akşam yerinden kaldırırken yardıma ihtiyacı var; tek başına güvenli değil. Kişi şimdi güvenle oturuyor. Bir akrabası reddetti. Bakım hizmetinin nöbetçi hattı açık, bu akşam bir çalışan ayarlayabilir. Normal e-posta yarın yanıtlanır. Leyla ararken güvenle oturabilirler.",question:"Bu akşamki ihtiyacı en doğrudan hangi istek karşılar?",options:[{id:"faith-4-staffed-line",text:"Nöbetçi bakım hattını arasın, bu akşam kaldırma yardımı istesin ve beklerken bakım verdiği kişi güvenle otursun.",feedback:"Bu seçim somut, acil işi adlandırıyor ve bu akşam ulaşılabilir kaynağı kullanıyor. Aramak davranışın kendisi; yardımın kesinleşmesi ayrı. Beklerken güvenlik değişirse uygun acil yardıma hemen ulaş."},{id:"faith-4-general-call",text:"Nöbetçi hattı arasın, yorucu haftasını anlatsın ve genel olarak hangi bakım desteklerini sunduklarını sorsun.",feedback:"Yükün genelini anlatmak devam eden bakıma yardımcı olabilir. Bu akşamki kaldırma ihtiyacı daha belirli ve ertelenemez. Önce o işi söyle. Sonra zaman ve güvenlik uygunsa sürekli desteği konuş."},{id:"faith-4-email-and-wait",text:"Tam kaldırma isteğini e-postayla göndersin, yarınki normal yanıtı beklerken bakım verdiği kişi güvenle otursun.",feedback:"E-posta belirli bir istek içeriyor ve güvenli olmayan tek başına kaldırmayı önlüyor. Ama yanıt zamanı bu akşamki ihtiyaca uymuyor. Nöbetçi hattını şimdi kullan; uygun yardımın gerçekten kesinleşip kesinleşmediğini kaydet."}],bestOptionId:"faith-4-staffed-line"}},carry:{takeaway:"Açık isteği iletmek senin işin. Desteğin gelmesi, kontrol edip takip edeceğin ayrı bir sonuç.",followUp:{questionId:"faith-4-related-support-return",question:"Bakım isteğini ilettin mi, yardım var mıydı, hangi ihtiyaç hâlâ karşılanmadı?",observationPrompt:"Hangi istek iletildi veya bakım sağlandı? Asıl sözündeki hangi iş hâlâ yerine getirilmeyi bekliyor?",adjustmentPrompt:"Bir sonraki denemenin sana uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Umut, somut bakıma eşlik edebilir",paragraphs:["İnşirâh 94:5–6, zorlukla beraber kolaylık üzerinden dinî bir umut kaynağı sunar. Güçlüğünün bugün, seçtiğin tarihte veya istediğin biçimde biteceğini göstermez. ODA’nın destek isteği günlük hayata yönelik bir uyarlamadır. Ayetlerden çıkarılmış dinî hüküm veya klinik etki değildir. [F08] Kendi içinde düşünebilir ya da yalnızca bir bakım adımı seçebilirsin.","Yapabileceklerin bir günün tamamı değil, kısa bir anla sınırlı olabilir. Şu an hangi ihtiyacı adlandırabileceğini ve güvenli hangi kişi veya hizmetin yanıt verebileceğini sor. İlk ulaştığın kişinin uygun olmaması, o kişiye dair bilgidir. Her şeyi tek başına taşıman gerektiğinin kanıtı değildir. Dinlenme veya uzman bakımı başlı başına değerli davranış olabilir. İkisini de hak etmek için önce iş bitirmen gerekmez. Bir sınır, başka bir söz vermekten daha iyi koruyabilir. Sabır, şükür veya affetmeyi istismara veya güvenli olmayan iletişime katlanma talimatı olarak kullanma."]},{heading:"Araştırma kategorileri imanını yargılayamaz",paragraphs:["Dinî başa çıkma derlemesi 49 çalışmada 13.512 katılımcıyı kapsıyordu. Çoğu gözleme ve kişilerin kendi bildirimine dayanıyordu. Sık anılan 0,33 ve 0,22 değerleri, birleştirilmiş Fisher z değerleridir; ham korelasyon değildir. İnanç grubu bildirilen 8.115 katılımcının yüzde 57’si Protestan, yüzde 28’i Katolikti. Bu payda bütün katılımcıları anlatmaz. İlişkiler nedenselliği veya İslami uygulamanın etkisini göstermiyor. Araştırma etiketleri, senin imanına dair bir hükme dönüşmemeli. [F13]","NIMH rehberi süren sıkıntı ve günlük işlerde zorlanmada uzman yardımını destekler. Yardımı daha erken istemen de mümkün. Dua veya isteğe bağlı manevi danışma sağlık hizmetine eşlik edebilir ama gereken tedavinin yerini tutmaz. Krizde veya kendine zarar verme düşüncelerinde bulunduğun ülkedeki kriz desteğine hemen ulaş. Hayati tehlikede yerel acil yardım hizmetlerini ara. ABD’de yaşayanlar 988’i arayabilir veya mesaj gönderebilir. [F20] Acil yardım için dersin sonucunu veya belirli bir sürenin dolmasını bekleme."]}],sourceIds:["F08","F13","F20"]}},{schemaVersion:2,revision:2,id:"faith-5",courseId:"faith",locale:"tr",title:"İyilik yaparken başka bir sözünü bozma",goal:"Yardımın istendiğinden emin ol. İşe yarayan kısmı sürdür. Bir deneme için günü ve en fazla kaç dakika ayıracağını belirle.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Yardım görüşmesi uzayıp duruyor mu? Haftanın gerçekten kaldırabileceği bir iyilik seç.",reason:{id:"faith-5-purpose-cost",label:"Bu sözü yerine getirebilmek için neye sınır koyacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Bakımı gücümün yettiği sınırda tutmak","Var olan başka bir sözümü korumak","Teşekkürü şart koşmadan işe yarayan yardım sunmak"]},why:{id:"faith-5-why",label:"Bu sözü yerine getirebilmek için neye sınır koyacaksın?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Sözüne dön: Ne yaptın, ne kolaylaştırdı, bedeli neydi? İşe yarayan davranışı ve gerekli desteği koru. Hz. Âişe’nin Buhârî’deki rivayeti küçük, düzenli işleri ve ölçülü olmayı vurgular. Art arda işaretlediğin günler iman ölçüsü değildir.","İyilik araştırmaları yapan kişi için mütevazı bir ortalama fayda buluyor. Garanti vermiyor, sınırlarını yok saymana izin de vermiyor. İşe yarayan işi koru, karşı tarafın bu yardımı istediğini netleştir. En fazla kaç dakika ayıracağını “Eylem” veya “En küçük adım” alanına yaz. Bir deneme için tarih seç. Şimdilik tekrar edip etmeyeceğini düşün. Yarın gözden geçirirken başka bir deneme için tarih seçebilirsin."],example:{title:"Yusuf zamanında bitiriyor",text:"Yusuf notlarına bakıyor. Komşusuna telefon rehberindeki birini aramayı öğretmek işe yaramış. Ama akşamlar bakım işiyle çakışıyor. Komşusu cumartesi öğle yemeğinden sonra iki dakikalık mesajlaşmayı kabul ediyor. Yusuf o kişiyi nasıl arayacağını adım adım yazıp gönderiyor, iki dakika içinde bitiriyor. Başka bir soru kalıyor. Yararlı mesajı ve koruduğu sınırı kaydediyor. Sonraki cumartesiyi düşünüyor ama o tarih için henüz bir anlaşmaları yok."}},move:{invitation:"Sözünün işe yarayan kısmını sürdür. İstenen tek işi ne zaman, kaç dakikada yapacağını belirle.",instructions:["Asıl sözünü koru. Boyutunu veya zamanını yalnızca bilinçli bir anlaşmayla değiştir.","Sınırı “Eylem” veya “En küçük adım” alanına yaz. İstersen ayrıntıları ODA dışında tut."],prompts:[],suggestions:{action:["Örnek: Merve’ye arama adımlarını 2 dakikada gönder","Serkan’ı ara, birini aramayı anlat; 5 dakikayı aşma."],minimum:["Kararlaştırdığımız kişiyi arama adımlarını 2 dakikada gönder","Kararlaştırdığımız kişiyi nasıl arayacağını 5 dakikada anlat"],cue:["Kararlaştırdığımız öğle yemeği bittikten hemen sonra","Çarşamba 18.00 için kararlaştırdığımız görüşme başlayınca"],place:["Mevcut mesajlaşmamızda","Kullanabildiğimiz mevcut telefon görüşmesinde"],minutes:[2,5],fallback:["Daha fazlası gerekiyorsa kesinleştirilmiş başka tarih öner","Daha fazlası gerekiyorsa ayrı bir zaman için anlaş"],observation:["Gönderdim mi? İsteniyor muydu? 2 dakikayı aştım mı?","Anlattım mı? İsteniyor muydu? 5 dakikayı aştım mı?"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Örnek: Merve’ye arama adımlarını 2 dakikada gönder",minimum:"Kararlaştırdığımız kişiyi arama adımlarını 2 dakikada gönder",cue:"Kararlaştırdığımız öğle yemeği bittikten hemen sonra",place:"Mevcut mesajlaşmamızda",fallback:"Daha fazlası gerekiyorsa kesinleştirilmiş başka tarih öner",observation:"Gönderdim mi? İsteniyor muydu? 2 dakikayı aştım mı?",minutes:2},{action:"Serkan’ı ara, birini aramayı anlat; 5 dakikayı aşma.",minimum:"Kararlaştırdığımız kişiyi nasıl arayacağını 5 dakikada anlat",cue:"Çarşamba 18.00 için kararlaştırdığımız görüşme başlayınca",place:"Kullanabildiğimiz mevcut telefon görüşmesinde",fallback:"Daha fazlası gerekiyorsa ayrı bir zaman için anlaş",observation:"Anlattım mı? İsteniyor muydu? 5 dakikayı aştım mı?",minutes:5}]},suggested:{action:"Örnek: Merve’ye arama adımlarını 2 dakikada gönder",minimum:"Kararlaştırdığımız kişiyi arama adımlarını 2 dakikada gönder",minutes:2,cueHint:"Kararlaştırdığımız öğle yemeği bittikten hemen sonra",placeHint:"Mevcut mesajlaşmamızda",obstacleHint:"Örnek: istek, kararlaştırdığımız iki dakikanın ötesine uzuyor",fallbackHint:"Daha fazlası gerekiyorsa kesinleştirilmiş başka tarih öner",observationHint:"Gönderdim mi? İsteniyor muydu? 2 dakikayı aştım mı?"},stopRule:"Sağlığını, uykunu, paranı ve mevcut sözlerini koru. Güvenli olmayan yardım veya iletişim zorunlu değil.",accessibleAlternative:"Yapabildiğin yardım biçimini seç. Dinlenmek, destek almak veya sınır koymak da bir seçenek."},result:{question:"Seçtiğin işi sınırların içinde yaptın mı?",observationPrompt:"Hangi yardım işe yaradı? Karşı taraf bu yardımı istiyor muydu? Koyduğun sınıra uyabildin mi?"},judgment:{primary:{id:"faith-5-task-boundary-decision",scenario:"Nermin’in komşusu perşembe randevusundan önce telefonuna kaydettiği birini aramayı öğrenmek istiyor. Çarşamba, Nermin’in sabit bakım işi öncesinde on boş dakika var. Komşusu on dakikalık arama istiyor; mesaj okumakta zorlanıyor. Cumartesi yirmi dakika var ama randevu geçmiş olacak.",question:"Yararlı işe ve iki kişinin koşullarına hangi plan uyuyor?",options:[{id:"faith-5-saturday-call",text:"Komşunun telefon adımlarını öğrenmeye daha çok zamanı olsun diye cumartesi günkü yirmi dakikalık görüşmeyi önersin.",feedback:"Cumartesi, Nermin’in bakım işini korur ve daha çok çalışma süresi verir. Ama perşembe ihtiyacını kaçırır. Bu kişi için kararlaştırılan çarşamba zamanını kullan. Cumartesiyi sonraki sorular için ayrı düşün."},{id:"faith-5-text-steps",text:"Bakım işini korumak ve yazılı tarif bırakmak için kayıtlı kişiyi arama adımlarını çarşamba günü mesajla göndersin.",feedback:"Mesaj zamanı korur ve sonradan bakılacak tarif bırakır. Komşusu mesaj okumakta zorlandığı için biçim gerçek ihtiyacı karşılamayabilir. Burada kararlaştırılmış kısa arama, onun kullanabildiği bir yol."},{id:"faith-5-ten-minute-call",text:"Çarşamba on dakikalık görüşmede tek kişiyi aramayı anlatsın, bitiş saatini söylesin ve bakım işi öncesinde dursun.",feedback:"Bu seçim randevu öncesi ihtiyacı, istenen ve kullanılabilir bir yolla karşılarken bakımı koruyor. Arama adımlarının anlatıldığını ve sınıra uyulduğunu kaydet. Başka soru, süreyi aşma zorunluluğu değil, ayrı bir fırsattır."}],bestOptionId:"faith-5-ten-minute-call"}},carry:{takeaway:"Haftana uyan, istenen tek işi koru. Sonraki seçime faydası ve verdiğin emek yön versin.",followUp:{questionId:"faith-5-bounded-occurrence-return",question:"Kararlaştırılan iş yararlı ve istenen bir iş miydi? Dakika sınırı diğer sözlerini korudu mu?",observationPrompt:"Hangi yararlı iş yapıldı, sınıra uyuldu mu, başka bir tarih kesinleşti mi?",adjustmentPrompt:"Bir sonraki denemenin sana uyması için neyi değiştirebilirsin?"}},goDeeper:{sections:[{heading:"Düzenli olmak, sınırsız olmak değildir",paragraphs:["Hz. Âişe’ye atfedilen rivayette Buhârî 6464 küçük, düzenli işleri ve ölçülü olmayı vurgular. Bölümün bütünü ameller ve kurtuluşla da ilgilidir. ODA sürdürülebilir bir davranış üzerine gönüllü bir günlük düşünme fırsatı çıkarır. Sayıya bakarak dinî değeri veya kurtuluşu yargılayamaz. Özel niyet, ibadet, kaçırılmış fırsat veya uygulamada tutulan seri, iman puanı değildir. [F11]","Tutmayı seçtiğin davranış ve destek kayıtlarına bak. Hangi parça amaca gerçekten hizmet etti? Ne kadar zaman ve emek istedi, hangi başka sözünü aksattı? Başka bir ritüel eklemek yerine o yararlı kısmı koru. Günlük veya haftalık tekrarı düşünebilirsin ama tek bir denemeyi yapacağın tarihi seç. Bu plan, o denemeyi ve ertesi gün dönüşünü kaydeder; tekrar eden düzeni değil. Yardımın istendiğini kesinleştir, yapabildiğin sınırı söyle ve ona uy. İhtiyaç gücünü aşıyorsa daha küçük teklif, başka kaynağa yönlendirme, dinlenme veya durmak sınırsız yardım sözü vermekten daha sorumlu olabilir. Teşekkür ve sıcak duygular tamamlanma şartı değildir."]},{heading:"İyilik araştırmalarında gerçekte ne denendi",paragraphs:["2018 iyilik derlemesi 4.045 katılımcının yer aldığı 27 çalışmayı birleştirdi. İyilik davranışları, yapan kişinin iyi oluşunda mütevazı ortalama fayda gösterdi. Örneklemler ve yöntemler farklıydı. Bu, her yapan veya alan kişiye fayda garanti etmez. Sevabı ölçmez, sınırsız kendinden vazgeçmeyi doğrulamaz. Etkiyi değiştiren etkenlerin veya yayın yanlılığının saptanmaması, yok olduklarını kanıtlamaz. [F16]","Ayrı bir deneyde, başkalarına iyilik grubundan dört hafta boyunca haftada bir günde üç iyilik istendi. İki hafta sonra takip ölçümü yapıldı. Altı hafta boyunca iyilik yapmaları istenmedi. Makalenin özetindeki katılımcı sayısı ile rastgele gruplara ayrılanların toplamı farklıydı; ana gelişim analizlerinde daha küçük grup kullanıldı. [F18] ODA’nın gücüne göre sınırladığın tek davranış planı farklı bir uyarlamadır. Sonraki gerçek fırsatı ancak hâlâ uyuyorsa planla. Yarın değerlendirirken işe yaradı mı, istendi mi ve ne kadar emek verdin, bunlara bakarsın. Bugün tekrar etmeni veya dinî seri tutmanı istemez."]}],sourceIds:["F11","F16","F18"]}}];function n(a,t){const e=a.judgment.primary,l=e.options.findIndex(r=>r.id===e.bestOptionId);return{id:a.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,practice:[a.move.instructions[0],a.move.instructions[1],"Gerçekte ne olduğunu kaydet. Yarın aynı denemeye geri bak."],reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:e.options.map(r=>r.text),correct:l,feedback:e.options[l].feedback,takeaway:a.carry.takeaway,sources:a.id==="faith-5"?[...a.goDeeper.sourceIds,"faith-kindness"]:a.goDeeper.sourceIds,photo:t}}const m={id:"faith",title:"Yardım etmeye niyet ettin. İnancın verdiğin bir söze yön versin.",subtitle:"5 isteğe bağlı ders. Anlamlı tek bir sözü dene, düşüncelerini özel tut, bakıma ve sınırlarına yer aç.",description:"İstersen inancınla ilgili düşüncelerin günlük bir işine yön versin. Düşünmek isteğe bağlı. Hazırlık, dürüst teşekkür, destek ve açık sınırlarla aynı sözü yeniden düzenle.",scope:"İnancın üzerine düşünmek için İslami kaynaklar ve isteğe bağlı günlük uygulamalar. Dinî kaynaklar ile psikolojik araştırmalar ayrı gösterilir. Kaygı veya zorlanma iman eksikliği sayılmaz. Bu ders dinî hüküm değildir; ruh sağlığı bakımının yerini tutmaz. Krizdeysen veya kendine zarar vermeyi düşünüyorsan yerel acil yardım numaranı ara.",outcome:"Denediğin veya ara verdiğin bir söz, sana özel düşünceler ve tarihini belirlediğin sonraki adım ya da destek.",photo:{id:"1767396024869-756a346dc39d",alt:"Kemerli kapıları ve ağaçları olan bir cami avlusu"},lang:"tr",lessons:[n(i[0],{id:"1778616364918-34490657598f",alt:"Elinde tespih tutan bir adam"}),n(i[1],{id:"1590682680695-43b964a3ae17",alt:"Toprağa fide diken eller"}),n(i[2],{id:"1634906346143-aacbc4c02fec",alt:"Masada bir gözlük yanında teşekkür notu"}),n(i[3],{id:"1570739260082-39a84dae80c8",alt:"Ahşap masada yanan bir fener"}),n(i[4],{id:"1710092784814-4a6f158913b8",alt:"Başka bir kadına yemek tabağı uzatan bir kadın"})]};export{m as COURSE,i as LESSONS_V2,d as SOURCES};
